const SRC_IR_IT_AG_WITNESS_COST_IS_TIGHT: &str = "def ir_it_ag_witness_cost_is_tight (spc : IRConst) (p : Nat) (q : Nat) : @Eq IROutcome (ir_eval (Nat.add (Nat.add (Nat.add (Nat.add ir_d4 ir_d2) ir_d4) ir_d2) ir_d1) (ir_itd_module spc) ir_d0 (ir_vl2 (IRScalar.ptr_ p) (IRScalar.ptr_ q)) ir_mem0 ir_d7) IROutcome.fuel_out := ir_itd_is_still_running_at_thirteen spc p q";

